"""12 expanded curriculum modules (ITP-07..10, IBT-07..10, IELTS-07..10) grounded in material_bank OER PDFs."""


def _mod(
    mid,
    exam_id,
    section,
    title,
    objective,
    theory,
    worked_example,
    common_mistake,
    difficulty,
    est_min,
    sort_idx,
    license_name,
    provenance,
    drills,
    audio_script=None,
):
    return {
        "id": mid,
        "examId": exam_id,
        "section": section,
        "title": title,
        "objective": objective,
        "theory": theory,
        "workedExample": worked_example,
        "commonMistake": common_mistake,
        "difficulty": difficulty,
        "estimatedMinutes": est_min,
        "sortIndex": sort_idx,
        "license": license_name,
        "provenance": provenance,
        "audioScript": audio_script,
        "drills": drills,
    }


def _d(did, prompt, opts, ans, exp, ttype="CHOICE_SINGLE", accepted=None):
    return {
        "id": did,
        "taskType": ttype,
        "prompt": prompt,
        "options": opts,
        "answer": ans,
        "acceptedAnswers": accepted if accepted is not None else [ans],
        "explanation": exp,
    }


